#!/bin/bash
# Gather the soundfonts of tests/render in a directory, for the GitHub workflows (Ubuntu).
# Usage: get_soundfonts.sh <soundfont directory>
# FluidR3_GM.sf2 and TimGM6mb.sf2 come from the packages fluid-soundfont-gm and timgm6mb-soundfont (installed before),
# VintageDreamsWaves-v2.sf2 and .sf3 from the sources of FluidSynth (checked). polyphone-test.sf2 is generated by
# tests/render/render.sh.

set -e
if [ $# -ne 1 ]; then
    echo "Usage: $0 <soundfont directory>"
    exit 1
fi
dir=$1
mkdir -p "$dir"

for file in FluidR3_GM.sf2 TimGM6mb.sf2; do
    if [ ! -f "/usr/share/sounds/sf2/$file" ]; then
        echo "/usr/share/sounds/sf2/$file not found (packages fluid-soundfont-gm and timgm6mb-soundfont)"
        exit 1
    fi
    ln -sf "/usr/share/sounds/sf2/$file" "$dir/$file"
done

url=https://raw.githubusercontent.com/FluidSynth/fluidsynth/v2.3.4/sf2
download() {
    local file=$1 sha256=$2
    if [ ! -f "$dir/$file" ] || ! echo "$sha256  $dir/$file" | sha256sum -c --quiet - 2> /dev/null; then
        curl -sSfL --retry 3 -o "$dir/$file" "$url/$file"
        echo "$sha256  $dir/$file" | sha256sum -c --quiet -
    fi
}
download VintageDreamsWaves-v2.sf2 52132b2b83994f0067d3a66b93b4f1b67d53ff8c0d3be90d39f23f92b4585cdd
download VintageDreamsWaves-v2.sf3 bbb921fa98a3705d304f05904f06952b75e1cfe1ada086590d36cbd6efec1a40

ls -l "$dir"
